package com.cenedu.backend.ai.problem.render;
import static org.assertj.core.api.Assertions.*; import com.cenedu.backend.ai.problem.adapter.SafeSvgSanitizer; import com.cenedu.backend.domain.problem.authoring.diagram.*; import java.util.*; import org.junit.jupiter.api.Test;
class ProblemDiagramRendererTest { @Test void identicalSpecProducesIdenticalSvgAndHash(){var s=new NumberLineDiagramSpecV1(1,"LINE",DiagramKind.NUMBER_LINE,new DiagramViewport(640,180,16),new DiagramStyle("#000000","#FFFFFF","#FF0000",1,"sans-serif",12),"MIN","MAX","STEP",List.of(),List.of(),false,false);var r=new ProblemDiagramRenderer(new SafeSvgSanitizer());var a=r.render(s,new DiagramRenderContext(Map.of()));var b=r.render(s,new DiagramRenderContext(Map.of()));assertThat(b.svg()).isEqualTo(a.svg());assertThat(b.sha256()).isEqualTo(a.sha256());assertThat(a.svg()).contains("viewBox=\"0 0 640 180\"");} }
